def transform(grid):
 n=len(grid[0]); c=n//2
 out=[[0]*n for _ in range(n)]
 for r in range(n):
  if r<=c:
   out[r][c-r]=2; out[r][c+r]=2
  else:
   for x in range(n):
    if (x-r-c)%4==0: out[r][x]=1
 return out
